sp_widget.client_script:
api.controller = function($scope, $interval, $timeout, $window) {
    $scope.qrUrl = '';
    $scope.recordSysId = '';
    $scope.loading = false;

    // Start Flow: Only create record & get QR
    $scope.triggerFlow = function() {
        $scope.loading = true;

        $scope.server.get({ action: 'createRecord' }).then(function(response) {
            $scope.recordSysId = response.data.sys_id;

            $timeout(function() {
                var stopPolling = $interval(function() {
                    $scope.server.get({ 
                        action: 'getRecord', 
                        sys_id: $scope.recordSysId 
                    }).then(function(res) {
                        if (res.data.url) {
                            $scope.qrUrl = res.data.url;
                            $scope.loading = false;

                            document.getElementById("qrcode").innerHTML = "";
                            new QRCode(document.getElementById("qrcode"), {
                                text: $scope.qrUrl,
                                width: 200,
                                height: 200
                            });

                            $interval.cancel(stopPolling);
                        }
                    });
                }, 3000);
            }, 4000);
        });
    };

    // Navigation
    $scope.goPrevious = function() {
        $window.location.href = "/fcc_kyc"; 
    };

    // Proceed: Update status then navigate
    $scope.goProceed = function() {
        if ($scope.recordSysId) {
            $scope.server.get({ 
                action: 'markStarted',
                sys_id: $scope.recordSysId
            }).then(function() {
                $window.location.href = "/fcc_kyc?id=fcc_kyc_update_entity_details"; 
            });
        } else {
            $window.location.href = "/fcc_kyc?id=fcc_kyc_update_entity_details"; 
        }
    };
};

sp_widget.css:
body {
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 0;
}

/* Breadcrumb Header */
.breadcrumb-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px 20px;
  border-bottom: 1px solid #ccc;
  background-color: #fff; /* white background */
}

.breadcrumb {
  font-size: 14px;
  color: #333;
  font-weight: bold;
}

.step-info {
  text-align: right;
  font-size: 14px;
  color: #333;
}

/* Section Title */
.section-title {
  text-align: center;
  font-size: 20px;
  font-weight: bold;
  margin: 20px 0;
  color: #333;
}

/* Document Layout */
.document-upload-layout {
  display: flex;
  flex-direction: column;
  gap: 25px;
  padding: 20px;
  background-color: #fff;
}

.upload-row {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-bottom: 25px;
}

.upload-row label {
  font-weight: bold;
  font-size: 16px;
  color: #333;
  min-width: 150px;
}

.input-group {
  display: flex;
  align-items: center;
  gap: 20px;
  flex: 1;
}

.uniform-select {
  width: 250px;  /* uniform dropdown width */
  padding: 6px;
  font-size: 14px;
  border: 1px solid #ccc;
  border-radius: 4px;
}

/* Buttons */
.button-container {
  display: flex;
  justify-content: flex-end;
  gap: 15px;
  padding: 20px;
  background-color: #fff;
}

.button-container button {
  padding: 10px 20px;
  font-size: 14px;
  font-weight: bold;
  color: white;
  background-color: #2563eb;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.button-container button:hover {
  background-color: #1e3a8a;
}



/* Checkbox Question */
.question-container {
  text-align: left;
  padding: 20px;
  background-color: #f8f9fa;
  border-top: 1px solid #ccc;
}

.question-container label {
  font-size: 15px;
  font-weight: bold;
  cursor: pointer;
}

.question-container input[type="checkbox"] {
  margin-right: 8px;
}

.only-holder-question {
  padding: 10px 20px;
  font-size: 14px;
  font-weight: bold;
  color: #333;
}

.required {
  color: red;
  font-weight: bold;
  margin-left: 3px;
}

body, .kyc-container {
    font-family: 'Segoe UI', sans-serif;
    max-width: 700px;
    margin: auto;
    padding: 30px;
  }

  .kyc-title {
    text-align: center;
    color: #2c3e50;
    font-size: 32px;      /* larger main heading */
    font-weight: bold;
    margin-bottom: 20px;
  }

  .kyc-subtitle {
    color: #34495e;
    font-size: 22px;      /* bigger sub-headings */
    margin-bottom: 15px;
  }

  .kyc-list {
    line-height: 1.8;
    color: #555;
    font-size: 18px;      /* larger list text */
  }

  .kyc-text {
    margin-top: 10px;
    color: #555;
    font-size: 18px;      /* spinner text */
  }

  .kyc-instructions {
    background-color: #f4f6f7;
    border-radius: 10px;
    padding: 20px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
  }

  .kyc-center {
    margin-top: 30px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
  }

  .kyc-qrcode {
    margin-top: 15px;
    padding: 15px;
    background: white;
    border: 1px solid #ccc;
    border-radius: 10px;
    display: inline-block;
  }

  .kyc-buttons {
    margin-top: 40px;
    display: flex;
    justify-content: flex-end;
    gap: 12px;
  }

  .kyc-button {
    font-size: 16px;      /* bigger button text */
    padding: 10px 20px;   /* more button padding */
  }

  .breadcrumb-header {
    font-size: 16px;
    margin-bottom: 20px;
  }

  .step-info {
    font-size: 18px;
    font-weight: 500;
    margin-top: 5px;
  }

sp_widget.script:
(function() {
    data.message = '';
    data.url = '';
    data.sys_id = '';

    var table = 'x_vuram_financia_0_fcc_kyc_entity_details';
    var userEmail = gs.getUser().getEmail();

    // Create record (NO status update here)
    if (input && input.action === 'createRecord') {
        var grInd = new GlideRecord(table);
        grInd.addQuery('email_id', userEmail);
        grInd.query();

        if (grInd.next()) {
            // just return sys_id
            data.sys_id = grInd.sys_id.toString();
        }
    }

    // Get QR record
    if (input && input.action === 'getRecord') {
        var gr2 = new GlideRecord(table);
        if (gr2.get(input.sys_id)) {
            data.url = gr2.getValue('video_kyc_link');
        }
    }

    // Update status when proceeding
    if (input && input.action === 'markStarted') {
        var gr3 = new GlideRecord(table);
        if (gr3.get(input.sys_id)) {
            gr3.video_kyc_status = "started";
            gr3.update();
            data.message = 'Record updated as started';
        }
    }
})();
